{"cells":[{"cell_type":"code","source":["\n","SELECT \n","    `data.startTime`,\n","    `data.additionalJson.UserGroup`,\n","    `data.additionalJson.Value`,\n","    `data.additionalJson.Count`\n","FROM `bronze_raw_data`.raw_fingrid_data  -- Full path: lakehouse.table\n","WHERE `data.additionalJson.UserGroup` IS NOT NULL\n","LIMIT 5;\n"],"outputs":[],"execution_count":null,"metadata":{"microsoft":{"language":"sparksql","language_group":"synapse_pyspark"},"collapsed":false},"id":"e62d8e4f-60f7-4694-8b93-134bf7a62354"},{"cell_type":"code","source":["\n","-- Drop if exists (in silver lakehouse)\n","DROP TABLE IF EXISTS silver_cleaned_consumption;\n","\n","-- Create silver table: Transform raw from bronze to clean in silver\n","CREATE TABLE silver_cleaned_consumption AS\n","SELECT \n","    CAST(`data.startTime` AS TIMESTAMP) as timestamp_utc,\n","    CAST(`data.endTime` AS TIMESTAMP) as timestamp_end_utc,  -- If endTime exists; adjust if not\n","    `data.additionalJson.UserGroup` as user_group,\n","    CAST(`data.additionalJson.Value` AS DECIMAL(18,2)) as consumption_kwh,\n","    CAST(`data.additionalJson.Count` AS INT) as accounting_points,\n","    CAST(DATE_FORMAT(CAST(`data.startTime` AS TIMESTAMP), 'yyyyMMdd') AS INT) as date_key,\n","    HOUR(CAST(`data.startTime` AS TIMESTAMP)) as hour_key,\n","    CAST(`data.startTime` AS DATE) as date,\n","    YEAR(CAST(`data.startTime` AS TIMESTAMP)) as year,\n","    MONTH(CAST(`data.startTime` AS TIMESTAMP)) as month,\n","    DAY(CAST(`data.startTime` AS TIMESTAMP)) as day_of_month,\n","    DAYOFWEEK(CAST(`data.startTime` AS TIMESTAMP)) as day_of_week,  -- 1=Sun, 7=Sat\n","    WEEKOFYEAR(CAST(`data.startTime` AS TIMESTAMP)) as week_of_year,\n","    QUARTER(CAST(`data.startTime` AS TIMESTAMP)) as quarter,\n","    DATE_FORMAT(CAST(`data.startTime` AS TIMESTAMP), 'EEEE') as day_name,  -- e.g., 'Monday'\n","    DATE_FORMAT(CAST(`data.startTime` AS TIMESTAMP), 'MMMM') as month_name,  -- e.g., 'October'\n","    CASE \n","        WHEN DAYOFWEEK(CAST(`data.startTime` AS TIMESTAMP)) IN (1, 7) THEN 1\n","        ELSE 0\n","    END as is_weekend,\n","    CASE \n","        WHEN MONTH(CAST(`data.startTime` AS TIMESTAMP)) IN (3, 4, 5) THEN 'Spring'\n","        WHEN MONTH(CAST(`data.startTime` AS TIMESTAMP)) IN (6, 7, 8) THEN 'Summer'\n","        WHEN MONTH(CAST(`data.startTime` AS TIMESTAMP)) IN (9, 10, 11) THEN 'Autumn'\n","        ELSE 'Winter'\n","    END as season,\n","    CASE \n","        WHEN HOUR(CAST(`data.startTime` AS TIMESTAMP)) >= 0 AND HOUR(CAST(`data.startTime` AS TIMESTAMP)) <= 5 THEN 'Night'\n","        WHEN HOUR(CAST(`data.startTime` AS TIMESTAMP)) >= 6 AND HOUR(CAST(`data.startTime` AS TIMESTAMP)) <= 11 THEN 'Morning'\n","        WHEN HOUR(CAST(`data.startTime` AS TIMESTAMP)) >= 12 AND HOUR(CAST(`data.startTime` AS TIMESTAMP)) <= 17 THEN 'Afternoon'\n","        ELSE 'Evening'\n","    END as period_of_day,\n","    CASE \n","        WHEN HOUR(CAST(`data.startTime` AS TIMESTAMP)) >= 7 AND HOUR(CAST(`data.startTime` AS TIMESTAMP)) <= 9 THEN 1\n","        WHEN HOUR(CAST(`data.startTime` AS TIMESTAMP)) >= 17 AND HOUR(CAST(`data.startTime` AS TIMESTAMP)) <= 20 THEN 1\n","        ELSE 0\n","    END as is_peak_hour,\n","    ROUND(\n","        CAST(`data.additionalJson.Value` AS DECIMAL(18,2)) / \n","        NULLIF(CAST(`data.additionalJson.Count` AS INT), 0),\n","        4\n","    ) as avg_per_point_kwh,\n","    `data.datasetId` as dataset_id,\n","    CURRENT_TIMESTAMP() as transformation_timestamp\n","FROM `bronze_raw_data`.raw_fingrid_data  -- Read from bronze lakehouse\n","WHERE \n","    `data.additionalJson.UserGroup` IS NOT NULL\n","    AND CAST(`data.additionalJson.Value` AS DECIMAL(18,2)) > 0\n","    AND CAST(`data.additionalJson.Count` AS INT) > 0;\n","\n","-- Verify (in silver lakehouse)\n","SELECT COUNT(*) as total_rows FROM silver_cleaned_consumption;  -- Expected: ~96,000\n","SELECT * FROM silver_cleaned_consumption LIMIT 5;  -- Sample rows\n","SELECT DISTINCT user_group FROM silver_cleaned_consumption ORDER BY user_group;  -- Expected: BE01 to BE14 (14 groups)\n"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":9,"statement_ids":[5,6,7,8,9],"state":"finished","livy_statement_state":"available","session_id":"0fd1fe94-3c64-4a85-b0b9-1beb8859abd0","normalized_state":"finished","queued_time":"2025-10-16T19:53:31.7586885Z","session_start_time":null,"execution_start_time":"2025-10-16T19:53:31.7590484Z","execution_finish_time":"2025-10-16T19:54:19.574725Z","parent_msg_id":"17329fbf-a252-457a-9386-d6f13ac1f684"},"text/plain":"StatementMeta(, 0fd1fe94-3c64-4a85-b0b9-1beb8859abd0, 9, Finished, Available, Finished)"},"metadata":{}},{"output_type":"execute_result","execution_count":4,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[]},"data":[]},"text/plain":"<Spark SQL result set with 0 rows and 0 fields>"},"metadata":{}},{"output_type":"execute_result","execution_count":4,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[]},"data":[]},"text/plain":"<Spark SQL result set with 0 rows and 0 fields>"},"metadata":{}},{"output_type":"execute_result","execution_count":4,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[{"name":"total_rows","type":"long","nullable":false,"metadata":{}}]},"data":[["10000"]]},"text/plain":"<Spark SQL result set with 1 rows and 1 fields>"},"metadata":{}},{"output_type":"execute_result","execution_count":4,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[{"name":"timestamp_utc","type":"timestamp","nullable":true,"metadata":{}},{"name":"timestamp_end_utc","type":"timestamp","nullable":true,"metadata":{}},{"name":"user_group","type":"string","nullable":true,"metadata":{}},{"name":"consumption_kwh","type":"decimal(18,2)","nullable":true,"metadata":{}},{"name":"accounting_points","type":